css:
.sc { display: flex; gap: .6rem; margin: 1.2rem 0 18px; }
.sc a { display: inline-grid; place-items: center; width: 2.7rem; height: 2.7rem; border-radius: 999px; border: 1.5px solid var(--bff-line, rgba(21,38,26,.22)); color: var(--os-color-heading); text-decoration: none; transition: background .2s, color .2s, border-color .2s; }
.sc a:hover { background: var(--os-color-heading); color: var(--os-color-background); border-color: var(--os-color-heading); }
.sc__i { display: grid; place-items: center; }
.sc svg { width: 1.3rem; height: 1.3rem; display: block; }
.sc__sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
@media (prefers-reduced-motion: reduce) { .sc a { transition: none; } }
